using Http;

@doc("商品レベルの静的フィールド（ColumnDefinition: common / product / product_size 準拠）")
model CatalogProductFields {
  @doc("大カテゴリ名")
  `category:depth1`?: string | null;

  @doc("中カテゴリ名")
  `category:depth2`?: string | null;

  @doc("総合コード")
  `product:code`?: string | null;

  @doc("一意総合コード")
  `product:unique_code`?: string | null;

  @doc("商品ID（自動採番。新規/更新判定に使用）")
  `product:id`?: string | null;

  @doc("メーカー名（import 時は名前→ID 解決）")
  `maker:name`?: string | null;

  @doc("シリーズ名（import 時は名前→ID 解決）")
  `series:name`?: string | null;

  @doc("シリーズ名カナ（自動）")
  `series:kana_name`?: string | null;

  @doc("シリーズID（自動）")
  `product:catalog_series_id`?: string | null;

  @doc("商品削除フラグ（import 時の削除指定用の制御列。export では常に null）")
  `meta:product_delete`?: string | null;

  @doc("商品タイプ")
  `product:product_type`?: string | null;

  @doc("新製品終了日")
  `product:new_product_end_date`?: string | null;

  @doc("掲載区分 name: 掲載 / 限定掲載 / 非掲載。【import】キーを含める場合は値必須（null / 空文字は「空欄指定」として 422）。新規商品を作るリクエストではキー自体の省略も 422")
  `product:listing_kind`?: string | null;

  @doc("表示カテゴリ区分 name（Catalog::DisplayCategoryKind の表示名）")
  `product:display_category_kind`?: string | null;

  @doc("粗利率ランク区分 name（Catalog::Product::GrossProfitRankKind の表示名。例: S / A / B / C / D）")
  `product:gross_profit_rank`?: string | null;

