  `product:delivery_date_kind`?: string | null;

  @doc("Pickup（○/×）")
  `product:is_pickup`?: string | null;

  @doc("お客様組立（○/×）")
  `product:is_self_construction`?: string | null;

  @doc("オリジナル（○/×）")
  `product:is_original`?: string | null;

  @doc("受注生産 name: ○ / × / 商品から継承")
