  `product:installation_service_kind`?: string | null;

  @doc("個人宅配送 name: 可 / 不可 / メーカーから継承")
  `product:individual_delivery_kind`?: string | null;

  @doc("出荷状態 name: 完成品 / 組立品 / メーカーから継承")
