using Http;
using OpenAPI;

@tag("webhooks")
@route("webhooks")
namespace NewKagg.V1.Webhooks.FinishSync {
  model FinishSyncRequest {
    @query
    @doc("EC 取り込み対象ディレクトリ名（YYYYMMDD_HHMMSS_cNN 形式。NN は chunk 連番。suffix なしの旧形式・手動同期の dir も受理する。対応する chunk が無い場合も 404 にはせず、NoContent（200）で no-op として受ける）")
    @example("20260710_150000_c00")
    @pattern("^\\d{8}_\\d{6}(_c\\d{2})?$")
    directory_name: string;
  }

  @get
  @route("/finish_sync")
  @doc("""
    EC 側（kagg-ec）が取り込み完了時に通知する webhook。
    旧 kaggdb の /data_sync/finish_sync/ 相当。
    directory_name から push 段の chunk（catalog_ec_sync_chunks.s3_path）を逆引きし、未完了の場合は
    ChunkPushJob を enqueue して result 回収を再開する。
    対応する chunk が無い場合・既に完了している場合は何もせず NoContent を返す。
    EC 側が任意ヘッダ・query を付けられないため認証は行わない（directory_name の逆引きのみで受ける）。
    """)
  @operationId("getWebhooksFinishSync")
  op finishSync(...FinishSyncRequest):
    | NoContent
    | BadRequest
    | GenericErrorResponse;
}

